-- Instala o modelo GitHub Pages + Supabase Auth, separado das tabelas antigas do PHP.
BEGIN;
-- Perfis usam o UUID autenticado; nenhuma senha é armazenada nas tabelas do aluguel.
CREATE TABLE IF NOT EXISTS public.rental_profiles(id uuid PRIMARY KEY REFERENCES auth.users(id),full_name text NOT NULL,email text NOT NULL);
-- Privilégios administrativos são concedidos somente pelo SQL de administração.
CREATE TABLE IF NOT EXISTS public.rental_admins(user_id uuid PRIMARY KEY REFERENCES auth.users(id));
-- Mantém os três imóveis e os preços em centavos.
CREATE TABLE IF NOT EXISTS public.rental_properties(id bigint PRIMARY KEY,name text NOT NULL,kind text NOT NULL,rent bigint NOT NULL CHECK(rent>0));
-- Os preços fixos não são reajustados por solicitações de obra dos inquilinos.
INSERT INTO public.rental_properties VALUES(1,'Barbearia','barber',60000),(2,'Loja','shop',65000),(3,'Casa','house',40000) ON CONFLICT(id) DO NOTHING;
-- Registra início, saída pretendida e ocupação efetiva sem encerramento automático.
CREATE TABLE IF NOT EXISTS public.rental_leases(id bigserial PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.rental_profiles(id),property_id bigint NOT NULL REFERENCES public.rental_properties(id),key_date date NOT NULL,planned_end date NOT NULL,due_day integer NOT NULL CHECK(due_day BETWEEN 1 AND 31),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','closed')));
-- Impede duas ocupações simultâneas do mesmo imóvel.
CREATE UNIQUE INDEX IF NOT EXISTS rental_occupied ON public.rental_leases(property_id) WHERE status='active';
-- Cada conta mantém apenas um aluguel ativo por vez.
CREATE UNIQUE INDEX IF NOT EXISTS rental_one_active ON public.rental_leases(user_id) WHERE status='active';
-- Guarda cada competência e sua composição; antecipações permanecem identificadas por mês.
CREATE TABLE IF NOT EXISTS public.rental_invoices(id bigserial PRIMARY KEY,lease_id bigint NOT NULL REFERENCES public.rental_leases(id),period text NOT NULL,due date NOT NULL,base bigint NOT NULL DEFAULT 0,extra bigint NOT NULL DEFAULT 0,extra_reason text NOT NULL DEFAULT '',discount bigint NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','paid','cancelled')),paid_at timestamptz,paid_amount bigint,mp_payment text,UNIQUE(lease_id,period));
-- Registra descontos documentados apenas para loja e barbearia.
CREATE TABLE IF NOT EXISTS public.rental_credits(id bigserial PRIMARY KEY,lease_id bigint NOT NULL REFERENCES public.rental_leases(id),kind text NOT NULL,description text NOT NULL,unit bigint NOT NULL,quantity integer NOT NULL,total bigint NOT NULL,parts integer NOT NULL,proof_path text NOT NULL,status text NOT NULL DEFAULT 'pending',review text NOT NULL DEFAULT '');
-- Evita reaplicar uma parcela já usada em determinada fatura.
CREATE TABLE IF NOT EXISTS public.rental_credit_parts(credit_id bigint REFERENCES public.rental_credits(id),invoice_id bigint REFERENCES public.rental_invoices(id),amount bigint NOT NULL,PRIMARY KEY(credit_id,invoice_id));
-- Cupons são criados pelo administrador com validade e limite de usos.
CREATE TABLE IF NOT EXISTS public.rental_coupons(id bigserial PRIMARY KEY,code text NOT NULL UNIQUE,amount bigint NOT NULL,expires date NOT NULL,max_uses integer NOT NULL,uses integer NOT NULL DEFAULT 0);
-- Aceita no máximo um cupom por fatura.
CREATE TABLE IF NOT EXISTS public.rental_coupon_uses(invoice_id bigint PRIMARY KEY REFERENCES public.rental_invoices(id),coupon_id bigint REFERENCES public.rental_coupons(id));
-- Um checkout pode pagar várias competências de um mesmo contrato.
CREATE TABLE IF NOT EXISTS public.rental_checkouts(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.rental_profiles(id),lease_id bigint NOT NULL REFERENCES public.rental_leases(id),amount bigint NOT NULL,created timestamptz NOT NULL DEFAULT now(),expires timestamptz NOT NULL DEFAULT now()+interval '30 minutes',status text NOT NULL DEFAULT 'pending',payment_id text,checkout_url text);
-- Congela o valor discriminado de cada fatura no momento da cobrança.
CREATE TABLE IF NOT EXISTS public.rental_checkout_items(checkout_id uuid REFERENCES public.rental_checkouts(id),invoice_id bigint REFERENCES public.rental_invoices(id),amount bigint NOT NULL,PRIMARY KEY(checkout_id,invoice_id));
-- Impede alteração ou outro checkout enquanto uma cobrança válida estiver reservando a fatura.
CREATE TABLE IF NOT EXISTS public.rental_invoice_locks(invoice_id bigint PRIMARY KEY REFERENCES public.rental_invoices(id),checkout_id uuid REFERENCES public.rental_checkouts(id),expires timestamptz NOT NULL);
-- Deduplica confirmação pelo identificador oficial de pagamento.
CREATE TABLE IF NOT EXISTS public.rental_payments(mp_id text PRIMARY KEY,checkout_id uuid REFERENCES public.rental_checkouts(id),amount bigint NOT NULL,paid_at timestamptz NOT NULL,status text NOT NULL);
-- A entrega é uma conferência administrativa; não autoriza apreensão de pertences.
CREATE TABLE IF NOT EXISTS public.rental_handovers(id bigserial PRIMARY KEY,lease_id bigint NOT NULL REFERENCES public.rental_leases(id),requested_date date NOT NULL,description text NOT NULL,keys_returned boolean NOT NULL,damaged boolean NOT NULL,status text NOT NULL DEFAULT 'pending');
-- Não duplica pedidos de entrega ainda em análise.
CREATE UNIQUE INDEX IF NOT EXISTS rental_one_handover ON public.rental_handovers(lease_id) WHERE status='pending';
-- Pausas interrompem somente novas competências acordadas, preservando dívida e ocupação.
CREATE TABLE IF NOT EXISTS public.rental_pauses(id bigserial PRIMARY KEY,lease_id bigint NOT NULL REFERENCES public.rental_leases(id),start_period text NOT NULL,end_period text,resume_period text,reason text NOT NULL,created timestamptz NOT NULL DEFAULT now());
-- Apenas uma pausa corrente por contrato.
CREATE UNIQUE INDEX IF NOT EXISTS rental_one_pause ON public.rental_pauses(lease_id) WHERE end_period IS NULL;
-- Chamados privados são vinculados à conta autenticada.
CREATE TABLE IF NOT EXISTS public.rental_tickets(id bigserial PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.rental_profiles(id),subject text NOT NULL,status text NOT NULL DEFAULT 'open',created timestamptz NOT NULL DEFAULT now());
-- Mensagens preservam autor e data sem editar o histórico.
CREATE TABLE IF NOT EXISTS public.rental_messages(id bigserial PRIMARY KEY,ticket_id bigint NOT NULL REFERENCES public.rental_tickets(id),sender_id uuid NOT NULL REFERENCES public.rental_profiles(id),body text NOT NULL,created timestamptz NOT NULL DEFAULT now());
-- Centraliza avisos e a fila de e-mail, sem duplicação por evento.
CREATE TABLE IF NOT EXISTS public.rental_notices(id bigserial PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.rental_profiles(id),subject text NOT NULL,body text NOT NULL,dedupe text NOT NULL UNIQUE,created timestamptz NOT NULL DEFAULT now(),emailed_at timestamptz);
-- Guarda inscrições push consentidas, sem expor os endereços ao público.
CREATE TABLE IF NOT EXISTS public.rental_push(id bigserial PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.rental_profiles(id),endpoint text NOT NULL UNIQUE,data jsonb NOT NULL);
-- Deduplica aviso push por mensagem e dispositivo.
CREATE TABLE IF NOT EXISTS public.rental_push_sent(subscription_id bigint REFERENCES public.rental_push(id) ON DELETE CASCADE,notice_id bigint REFERENCES public.rental_notices(id),PRIMARY KEY(subscription_id,notice_id));
-- Auditoria guarda decisões e identificadores, não senhas nem tokens.
CREATE TABLE IF NOT EXISTS public.rental_audit(id bigserial PRIMARY KEY,actor uuid,action text NOT NULL,detail jsonb NOT NULL DEFAULT '{}'::jsonb,created timestamptz NOT NULL DEFAULT now());
-- Calcula aluguel, adicionais, descontos e R$ 1,50 por dia após o vencimento.
CREATE OR REPLACE FUNCTION public.rental_total(i public.rental_invoices) RETURNS bigint LANGUAGE sql STABLE SET search_path='' AS $$ SELECT GREATEST(0,i.base+i.extra-i.discount)+GREATEST(0,CURRENT_DATE-i.due)*150::bigint $$;
-- Ajusta vencimentos nos meses que não possuem o dia informado.
CREATE OR REPLACE FUNCTION public.rental_due(m date,d integer) RETURNS date LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT m+(LEAST(d,EXTRACT(day FROM (m+interval '1 month - 1 day'))::integer)-1) $$;
-- Cria perfil após cadastro Auth, ignorando quaisquer metadados que tentem conceder privilégio.
CREATE OR REPLACE FUNCTION public.rental_new_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.rental_profiles(id,full_name,email) VALUES(NEW.id,COALESCE(NULLIF(trim(NEW.raw_user_meta_data->>'full_name'),''),'Cadastro pendente'),COALESCE(NEW.email,'')) ON CONFLICT(id) DO NOTHING; RETURN NEW; END $$;
-- Instala o gatilho uma única vez sem substituir outros gatilhos do projeto.
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='rental_auth_profile') THEN CREATE TRIGGER rental_auth_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE PROCEDURE public.rental_new_profile(); END IF; END $$;
-- Prepara também os perfis de usuários que já existem no Auth.
INSERT INTO public.rental_profiles SELECT id,COALESCE(NULLIF(trim(raw_user_meta_data->>'full_name'),''),'Cadastro pendente'),COALESCE(email,'') FROM auth.users ON CONFLICT(id) DO NOTHING;
-- Emite competências atuais ou antecipadas sem duplicar registros nem cobrar períodos pausados.
CREATE OR REPLACE FUNCTION public.rental_generate(p_lease bigint,p_until date DEFAULT CURRENT_DATE) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE l record; m date; d date; BEGIN SELECT a.*,p.rent INTO l FROM public.rental_leases a JOIN public.rental_properties p ON p.id=a.property_id WHERE a.id=p_lease AND a.status='active'; IF NOT FOUND THEN RETURN; END IF; m=date_trunc('month',l.key_date)::date; IF p_until>date_trunc('month',CURRENT_DATE)+interval '60 months' THEN RAISE EXCEPTION 'Antecipação limitada a 60 meses.'; END IF; WHILE m<=date_trunc('month',p_until)::date LOOP IF NOT EXISTS(SELECT 1 FROM public.rental_pauses z WHERE z.lease_id=l.id AND to_char(m,'YYYY-MM')>=z.start_period AND (z.end_period IS NULL OR to_char(m,'YYYY-MM')<z.end_period)) THEN d=GREATEST(public.rental_due(m,l.due_day),l.key_date); INSERT INTO public.rental_invoices(lease_id,period,due,base) VALUES(l.id,to_char(m,'YYYY-MM'),d,l.rent) ON CONFLICT(lease_id,period) DO NOTHING; END IF; m=(m+interval '1 month')::date; END LOOP; END $$;
-- Distribui apenas descontos aprovados, sem abater acima do saldo nem modificar checkout ativo.
CREATE OR REPLACE FUNCTION public.rental_allocate(p_lease bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE c record; i record; remaining bigint; amount bigint; BEGIN FOR c IN SELECT x.* FROM public.rental_credits x JOIN public.rental_leases l ON l.id=x.lease_id JOIN public.rental_properties p ON p.id=l.property_id WHERE x.lease_id=p_lease AND x.status='approved' AND p.kind<>'house' ORDER BY x.id LOOP SELECT c.total-COALESCE(SUM(z.amount),0) INTO remaining FROM public.rental_credit_parts z WHERE z.credit_id=c.id; FOR i IN SELECT f.* FROM public.rental_invoices f WHERE f.lease_id=p_lease AND f.status='open' AND NOT EXISTS(SELECT 1 FROM public.rental_invoice_locks k WHERE k.invoice_id=f.id AND k.expires>now()) AND NOT EXISTS(SELECT 1 FROM public.rental_credit_parts z WHERE z.credit_id=c.id AND z.invoice_id=f.id) ORDER BY f.period LOOP EXIT WHEN remaining<=0; amount=LEAST(remaining,CEIL(c.total::numeric/c.parts)::bigint,GREATEST(0,i.base-i.discount)); IF amount>0 THEN INSERT INTO public.rental_credit_parts VALUES(c.id,i.id,amount); UPDATE public.rental_invoices SET discount=discount+amount WHERE id=i.id; remaining=remaining-amount; END IF; END LOOP; END LOOP; END $$;
-- Devolve uma visão autorizada do painel; o ator é definido pela Edge Function após validar o JWT.
CREATE OR REPLACE FUNCTION public.rental_snapshot(p_actor uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE adm boolean; l record; result jsonb; BEGIN IF NOT EXISTS(SELECT 1 FROM public.rental_profiles WHERE id=p_actor) THEN RAISE EXCEPTION 'Conta não encontrada.'; END IF; adm=EXISTS(SELECT 1 FROM public.rental_admins WHERE user_id=p_actor); PERFORM pg_advisory_xact_lock(18402672); FOR l IN SELECT id FROM public.rental_leases WHERE status='active' AND (adm OR user_id=p_actor) LOOP PERFORM public.rental_generate(l.id); PERFORM public.rental_allocate(l.id); END LOOP; SELECT jsonb_build_object('profile',(SELECT to_jsonb(p) FROM public.rental_profiles p WHERE p.id=p_actor),'admin',adm,'properties',(SELECT COALESCE(jsonb_agg(to_jsonb(p)||jsonb_build_object('occupied',EXISTS(SELECT 1 FROM public.rental_leases z WHERE z.property_id=p.id AND z.status='active')) ORDER BY p.id),'[]'::jsonb) FROM public.rental_properties p),'leases',(SELECT COALESCE(jsonb_agg(to_jsonb(a)||jsonb_build_object('property',p.name,'kind',p.kind,'tenant',u.full_name,'overdue_months',(SELECT COUNT(DISTINCT f.period) FROM public.rental_invoices f WHERE f.lease_id=a.id AND f.status='open' AND f.base>0 AND f.due<CURRENT_DATE)) ORDER BY a.id),'[]'::jsonb) FROM public.rental_leases a JOIN public.rental_properties p ON p.id=a.property_id JOIN public.rental_profiles u ON u.id=a.user_id WHERE adm OR a.user_id=p_actor),'invoices',(SELECT COALESCE(jsonb_agg(to_jsonb(f)||jsonb_build_object('total',CASE WHEN f.status='paid' THEN f.paid_amount WHEN f.status='cancelled' THEN 0 ELSE public.rental_total(f) END,'property',p.name,'tenant',u.full_name) ORDER BY f.due,f.id),'[]'::jsonb) FROM public.rental_invoices f JOIN public.rental_leases a ON a.id=f.lease_id JOIN public.rental_properties p ON p.id=a.property_id JOIN public.rental_profiles u ON u.id=a.user_id WHERE adm OR a.user_id=p_actor),'credits',(SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.id DESC),'[]'::jsonb) FROM public.rental_credits c JOIN public.rental_leases a ON a.id=c.lease_id WHERE adm OR a.user_id=p_actor),'handovers',(SELECT COALESCE(jsonb_agg(to_jsonb(h) ORDER BY h.id DESC),'[]'::jsonb) FROM public.rental_handovers h JOIN public.rental_leases a ON a.id=h.lease_id WHERE adm OR a.user_id=p_actor),'pauses',(SELECT COALESCE(jsonb_agg(to_jsonb(z) ORDER BY z.id DESC),'[]'::jsonb) FROM public.rental_pauses z JOIN public.rental_leases a ON a.id=z.lease_id WHERE adm OR a.user_id=p_actor),'tickets',(SELECT COALESCE(jsonb_agg(to_jsonb(t)||jsonb_build_object('tenant',u.full_name) ORDER BY t.id DESC),'[]'::jsonb) FROM public.rental_tickets t JOIN public.rental_profiles u ON u.id=t.user_id WHERE adm OR t.user_id=p_actor),'messages',(SELECT COALESCE(jsonb_agg(to_jsonb(m)||jsonb_build_object('sender',u.full_name) ORDER BY m.id),'[]'::jsonb) FROM public.rental_messages m JOIN public.rental_tickets t ON t.id=m.ticket_id JOIN public.rental_profiles u ON u.id=m.sender_id WHERE adm OR t.user_id=p_actor),'notices',(SELECT COALESCE(jsonb_agg(to_jsonb(n) ORDER BY n.id DESC),'[]'::jsonb) FROM (SELECT * FROM public.rental_notices WHERE user_id=p_actor ORDER BY id DESC LIMIT 50) n)) INTO result; RETURN result; END $$;
-- Confirma operações financeiras e administrativas com transação, validação e bloqueio compartilhados.
CREATE OR REPLACE FUNCTION public.rental_action(p_actor uuid,p_action text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
-- Declara registros e valores usados pelas operações do painel.
DECLARE adm boolean; l record; p record; f record; c record; t record; z record; ids bigint[]; new_id bigint; qty integer; parts integer; unit bigint; value bigint; m date; until_date date; key_day date; intended date; ref uuid; reason text; kind text; body text; n integer;
-- Valida identidade antes de iniciar a operação.
BEGIN
-- Somente identidades Auth já reconhecidas podem executar ações.
IF NOT EXISTS(SELECT 1 FROM public.rental_profiles WHERE rental_profiles.id=p_actor) THEN RAISE EXCEPTION 'Conta não encontrada.'; END IF;
-- Privilégio depende da tabela administrativa, nunca de um campo enviado pelo navegador.
adm=EXISTS(SELECT 1 FROM public.rental_admins WHERE user_id=p_actor);
-- Serializa contratos, descontos e confirmações entre requisições concorrentes.
PERFORM pg_advisory_xact_lock(18402672);
-- Descarta reservas expiradas sem excluir o histórico do checkout.
DELETE FROM public.rental_invoice_locks WHERE expires<=now();
-- Registra um contrato somente após login e confirmação do Auth.
IF p_action='lease' THEN
-- Valida data da chave e saída pretendida de todos os imóveis.
key_day=(p_data->>'key_date')::date; intended=(p_data->>'planned_end')::date; IF key_day<CURRENT_DATE-interval '60 months' OR key_day>CURRENT_DATE OR intended<key_day OR intended<CURRENT_DATE OR intended>CURRENT_DATE+interval '60 months' THEN RAISE EXCEPTION 'Informe a data real da chave e uma saída prevista de até 60 meses.'; END IF;
-- Verifica imóvel, ocupação e conta antes de reservar.
SELECT * INTO p FROM public.rental_properties WHERE rental_properties.id=(p_data->>'property_id')::bigint; IF NOT FOUND THEN RAISE EXCEPTION 'Imóvel inválido.'; END IF; IF EXISTS(SELECT 1 FROM public.rental_leases WHERE status='active' AND (property_id=p.id OR user_id=p_actor)) THEN RAISE EXCEPTION 'Imóvel ou conta já possui aluguel ativo.'; END IF;
-- Define dia 20 para barbearia e dia da chave para loja ou casa.
INSERT INTO public.rental_leases(user_id,property_id,key_date,planned_end,due_day) VALUES(p_actor,p.id,key_day,intended,CASE WHEN p.kind='barber' THEN 20 ELSE EXTRACT(day FROM key_day)::integer END) RETURNING rental_leases.id INTO new_id; PERFORM public.rental_generate(new_id);
-- Obtém o contrato do titular ou o contrato selecionado pelo administrador.
ELSIF p_action IN('plan','advance','credit','handover','pause','resume_request','resume_confirm') THEN
-- A associação com o usuário é verificada mesmo se o identificador for adulterado.
SELECT a.*,b.kind,b.rent INTO l FROM public.rental_leases a JOIN public.rental_properties b ON b.id=a.property_id WHERE a.id=(p_data->>'lease_id')::bigint AND a.status='active'; IF NOT FOUND OR (NOT adm AND l.user_id<>p_actor) THEN RAISE EXCEPTION 'Contrato não encontrado.'; END IF; PERFORM public.rental_generate(l.id);
-- Altera somente a intenção de saída, sem encerrar contrato ou cancelar dívida.
IF p_action='plan' THEN intended=(p_data->>'planned_end')::date; IF intended<GREATEST(l.key_date,CURRENT_DATE) OR intended>CURRENT_DATE+interval '60 months' THEN RAISE EXCEPTION 'Data prevista inválida.'; END IF; UPDATE public.rental_leases SET planned_end=intended WHERE rental_leases.id=l.id;
-- Prepara antecipação por quantidade de meses ou até a saída pretendida.
ELSIF p_action='advance' THEN IF EXISTS(SELECT 1 FROM public.rental_pauses WHERE lease_id=l.id AND end_period IS NULL) THEN RAISE EXCEPTION 'Contrato pausado: solicite a retomada ao administrador.'; END IF; m=date_trunc('month',CURRENT_DATE)::date; IF EXISTS(SELECT 1 FROM public.rental_invoices WHERE lease_id=l.id AND period=to_char(m,'YYYY-MM') AND status='paid') THEN m=(m+interval '1 month')::date; END IF; IF p_data->>'mode'='end' THEN until_date=l.planned_end; ELSE n=(p_data->>'months')::integer; IF n<1 OR n>60 THEN RAISE EXCEPTION 'Escolha de 1 a 60 meses.'; END IF; until_date=(m+(n-1)*interval '1 month')::date; END IF; IF date_trunc('month',until_date)<m OR until_date>l.planned_end THEN RAISE EXCEPTION 'A antecipação precisa caber na permanência prevista. Atualize a previsão primeiro.'; END IF; PERFORM public.rental_generate(l.id,until_date); PERFORM public.rental_allocate(l.id);
-- A casa não permite descontos por obras, cortes, manutenção ou cupons.
ELSIF p_action='credit' THEN IF l.kind='house' THEN RAISE EXCEPTION 'Casa: aluguel fixo de R$ 400,00, sem desconto por obras.'; END IF; kind=p_data->>'kind'; unit=(p_data->>'unit')::bigint; qty=CASE WHEN kind='haircut' THEN (p_data->>'quantity')::integer ELSE 1 END; parts=(p_data->>'parts')::integer; IF kind NOT IN('haircut','maintenance') OR (kind='haircut' AND l.kind<>'barber') OR unit<1 OR unit>100000000 OR qty<1 OR qty>10000 OR parts<1 OR parts>36 OR length(trim(p_data->>'description'))<8 OR length(p_data->>'description')>1500 OR p_data->>'proof_path' NOT LIKE p_actor::text||'/%' THEN RAISE EXCEPTION 'Solicitação ou comprovante inválido.'; END IF; INSERT INTO public.rental_credits(lease_id,kind,description,unit,quantity,total,parts,proof_path) VALUES(l.id,kind,p_data->>'description',unit,qty,unit*qty,parts,p_data->>'proof_path');
-- Solicita entrega com data declarada e sem dívida já exigível.
ELSIF p_action='handover' THEN intended=(p_data->>'requested_date')::date; IF intended<CURRENT_DATE OR intended>CURRENT_DATE+interval '12 months' OR length(trim(p_data->>'description'))<10 OR length(p_data->>'description')>1500 THEN RAISE EXCEPTION 'Informe a data e as condições da entrega.'; END IF; IF EXISTS(SELECT 1 FROM public.rental_invoices WHERE lease_id=l.id AND status='open' AND (due<=CURRENT_DATE OR period<=to_char(CURRENT_DATE,'YYYY-MM'))) THEN RAISE EXCEPTION 'Quite os meses e cobranças já exigíveis antes de solicitar a entrega.'; END IF; IF EXISTS(SELECT 1 FROM public.rental_credits q WHERE q.lease_id=l.id AND q.status='approved' AND q.total>(SELECT COALESCE(SUM(a.amount),0) FROM public.rental_credit_parts a WHERE a.credit_id=q.id)) THEN RAISE EXCEPTION 'Concilie descontos parcelados restantes com a administração.'; END IF; INSERT INTO public.rental_handovers(lease_id,requested_date,description,keys_returned,damaged) VALUES(l.id,intended,p_data->>'description',COALESCE((p_data->>'keys_returned')::boolean,false),COALESCE((p_data->>'damaged')::boolean,false));
-- Pausa administrativa exige dois meses vencidos e justificativa registrada.
ELSIF p_action='pause' THEN IF NOT adm THEN RAISE EXCEPTION 'Ação administrativa.'; END IF; reason=trim(p_data->>'reason'); IF length(reason)<10 OR length(reason)>500 OR (SELECT COUNT(DISTINCT period) FROM public.rental_invoices WHERE lease_id=l.id AND status='open' AND base>0 AND due<CURRENT_DATE)<2 THEN RAISE EXCEPTION 'Pausa exige justificativa e pelo menos dois meses vencidos.'; END IF; INSERT INTO public.rental_pauses(lease_id,start_period,reason) VALUES(l.id,to_char(CURRENT_DATE+interval '1 month','YYYY-MM'),reason) RETURNING rental_pauses.id INTO new_id; INSERT INTO public.rental_notices(user_id,subject,body,dedupe) VALUES(l.user_id,'Atualização do contrato','Foi registrada uma pausa negociada de novas competências. Consulte o contrato e os débitos na sua conta.','pause:'||new_id) ON CONFLICT(dedupe) DO NOTHING;
-- Retomada cria a próxima competência, além da quitação da dívida anterior.
ELSIF p_action='resume_request' THEN IF NOT adm THEN RAISE EXCEPTION 'Ação administrativa.'; END IF; IF EXISTS(SELECT 1 FROM public.rental_invoices WHERE lease_id=l.id AND status='open' AND due<=CURRENT_DATE) THEN RAISE EXCEPTION 'Quite primeiro os débitos vencidos.'; END IF; SELECT * INTO z FROM public.rental_pauses WHERE lease_id=l.id AND end_period IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Contrato não está pausado.'; END IF; m=date_trunc('month',CURRENT_DATE+interval '1 month')::date; INSERT INTO public.rental_invoices(lease_id,period,due,base) VALUES(l.id,to_char(m,'YYYY-MM'),public.rental_due(m,l.due_day),l.rent) ON CONFLICT(lease_id,period) DO NOTHING; UPDATE public.rental_pauses SET resume_period=to_char(m,'YYYY-MM') WHERE rental_pauses.id=z.id;
-- Confirma a retomada somente após os débitos e a próxima competência estarem pagos.
ELSIF p_action='resume_confirm' THEN IF NOT adm THEN RAISE EXCEPTION 'Ação administrativa.'; END IF; SELECT * INTO z FROM public.rental_pauses WHERE lease_id=l.id AND end_period IS NULL; IF NOT FOUND OR z.resume_period IS NULL OR NOT EXISTS(SELECT 1 FROM public.rental_invoices WHERE lease_id=l.id AND period=z.resume_period AND status='paid') OR EXISTS(SELECT 1 FROM public.rental_invoices WHERE lease_id=l.id AND status='open' AND period<=z.resume_period) THEN RAISE EXCEPTION 'Quite a dívida e o próximo mês antes de confirmar a retomada.'; END IF; UPDATE public.rental_pauses SET end_period=resume_period WHERE rental_pauses.id=z.id;
-- Finaliza as ações de contrato.
END IF;
-- Aplica cupons somente em faturas sem checkout e sem contrariar o preço fixo da casa.
ELSIF p_action='coupon' THEN SELECT i.*,a.user_id,b.kind INTO f FROM public.rental_invoices i JOIN public.rental_leases a ON a.id=i.lease_id JOIN public.rental_properties b ON b.id=a.property_id WHERE i.id=(p_data->>'invoice_id')::bigint; IF NOT FOUND OR (NOT adm AND f.user_id<>p_actor) OR f.status<>'open' OR f.kind='house' OR EXISTS(SELECT 1 FROM public.rental_invoice_locks WHERE invoice_id=f.id) THEN RAISE EXCEPTION 'Cupom indisponível para esta fatura.'; END IF; SELECT * INTO c FROM public.rental_coupons WHERE code=upper(trim(p_data->>'code')) AND expires>=CURRENT_DATE AND uses<max_uses; IF NOT FOUND THEN RAISE EXCEPTION 'Cupom inválido ou esgotado.'; END IF; INSERT INTO public.rental_coupon_uses VALUES(f.id,c.id); UPDATE public.rental_coupons SET uses=uses+1 WHERE rental_coupons.id=c.id; UPDATE public.rental_invoices SET discount=discount+LEAST(c.amount,GREATEST(0,base-discount)) WHERE rental_invoices.id=f.id;
-- Cria cupons fixos com validade e limite de uso.
ELSIF p_action='coupon_create' THEN IF NOT adm THEN RAISE EXCEPTION 'Ação administrativa.'; END IF; IF (p_data->>'code')!~'^[A-Za-z0-9_-]{3,30}$' OR (p_data->>'amount')::bigint<1 OR (p_data->>'uses')::integer NOT BETWEEN 1 AND 10000 OR (p_data->>'expires')::date<CURRENT_DATE THEN RAISE EXCEPTION 'Cupom inválido.'; END IF; INSERT INTO public.rental_coupons(code,amount,expires,max_uses) VALUES(upper(p_data->>'code'),(p_data->>'amount')::bigint,(p_data->>'expires')::date,(p_data->>'uses')::integer);
-- Analisa comprovantes sem permitir descontos na casa.
ELSIF p_action='credit_review' THEN IF NOT adm THEN RAISE EXCEPTION 'Ação administrativa.'; END IF; SELECT q.*,b.kind INTO c FROM public.rental_credits q JOIN public.rental_leases a ON a.id=q.lease_id JOIN public.rental_properties b ON b.id=a.property_id WHERE q.id=(p_data->>'credit_id')::bigint AND q.status='pending'; IF NOT FOUND OR c.kind='house' OR length(trim(p_data->>'reason'))<5 OR length(p_data->>'reason')>500 OR p_data->>'status' NOT IN('approved','rejected') THEN RAISE EXCEPTION 'Análise inválida.'; END IF; UPDATE public.rental_credits SET status=p_data->>'status',review=p_data->>'reason' WHERE rental_credits.id=c.id; PERFORM public.rental_allocate(c.lease_id);
-- Altera somente o dia das próximas competências ainda não emitidas.
ELSIF p_action='due' THEN IF NOT adm OR (p_data->>'day')::integer NOT BETWEEN 1 AND 31 THEN RAISE EXCEPTION 'Vencimento inválido.'; END IF; UPDATE public.rental_leases SET due_day=(p_data->>'day')::integer WHERE rental_leases.id=(p_data->>'lease_id')::bigint AND status='active';
-- Confere entrega e cobra R$ 600 por danos da casa ou R$ 200 nos imóveis comerciais.
ELSIF p_action='handover_review' THEN IF NOT adm THEN RAISE EXCEPTION 'Ação administrativa.'; END IF; SELECT h.*,a.user_id,b.kind INTO t FROM public.rental_handovers h JOIN public.rental_leases a ON a.id=h.lease_id JOIN public.rental_properties b ON b.id=a.property_id WHERE h.id=(p_data->>'handover_id')::bigint AND h.status IN('pending','charged'); IF NOT FOUND THEN RAISE EXCEPTION 'Entrega indisponível.'; END IF; IF COALESCE((p_data->>'charge')::boolean,false) THEN IF t.status<>'pending' OR length(trim(p_data->>'reason'))<10 OR length(p_data->>'reason')>500 THEN RAISE EXCEPTION 'Explique os danos ou a falta de chaves.'; END IF; value=CASE WHEN t.kind='house' THEN 60000 ELSE 20000 END; INSERT INTO public.rental_invoices(lease_id,period,due,extra,extra_reason) VALUES(t.lease_id,'ENTREGA-'||t.id,CURRENT_DATE,value,p_data->>'reason'); UPDATE public.rental_handovers SET status='charged' WHERE rental_handovers.id=t.id; ELSE IF NOT COALESCE((p_data->>'keys_confirmed')::boolean,false) THEN RAISE EXCEPTION 'Confirme a conferência da devolução das chaves antes de encerrar.'; END IF; IF t.requested_date>CURRENT_DATE OR EXISTS(SELECT 1 FROM public.rental_invoices WHERE lease_id=t.lease_id AND status='open' AND (due<=CURRENT_DATE OR period<=to_char(CURRENT_DATE,'YYYY-MM'))) THEN RAISE EXCEPTION 'Aguarde a data da entrega e quite as cobranças exigíveis.'; END IF; IF EXISTS(SELECT 1 FROM public.rental_invoice_locks k JOIN public.rental_invoices i ON i.id=k.invoice_id WHERE i.lease_id=t.lease_id) THEN RAISE EXCEPTION 'Há checkout em andamento; concilie antes de encerrar.'; END IF; UPDATE public.rental_invoices SET status='cancelled' WHERE lease_id=t.lease_id AND status='open' AND due>CURRENT_DATE; UPDATE public.rental_leases SET status='closed' WHERE rental_leases.id=t.lease_id; UPDATE public.rental_handovers SET status='accepted',keys_returned=true WHERE rental_handovers.id=t.id; END IF;
-- Abre chamado privado com limites de tamanho e quantidade.
ELSIF p_action='ticket_open' THEN body=trim(p_data->>'message'); IF length(trim(p_data->>'subject')) NOT BETWEEN 4 AND 120 OR length(body) NOT BETWEEN 2 AND 4000 OR (SELECT COUNT(*) FROM public.rental_tickets WHERE user_id=p_actor AND status='open')>=10 THEN RAISE EXCEPTION 'Confira o assunto, a mensagem e o limite de chamados.'; END IF; INSERT INTO public.rental_tickets(user_id,subject) VALUES(p_actor,p_data->>'subject') RETURNING rental_tickets.id INTO new_id; INSERT INTO public.rental_messages(ticket_id,sender_id,body) VALUES(new_id,p_actor,body);
-- Responde ou encerra chamado após verificar titularidade.
ELSIF p_action IN('ticket_message','ticket_status') THEN SELECT * INTO t FROM public.rental_tickets WHERE rental_tickets.id=(p_data->>'ticket_id')::bigint; IF NOT FOUND OR (NOT adm AND t.user_id<>p_actor) THEN RAISE EXCEPTION 'Chamado não encontrado.'; END IF; IF p_action='ticket_status' THEN IF NOT adm OR p_data->>'status' NOT IN('open','closed') THEN RAISE EXCEPTION 'Ação administrativa.'; END IF; UPDATE public.rental_tickets SET status=p_data->>'status' WHERE rental_tickets.id=t.id; ELSE body=trim(p_data->>'message'); IF t.status<>'open' OR length(body) NOT BETWEEN 2 AND 4000 THEN RAISE EXCEPTION 'Confira a mensagem e se o chamado está aberto.'; END IF; INSERT INTO public.rental_messages(ticket_id,sender_id,body) VALUES(t.id,p_actor,body) RETURNING rental_messages.id INTO new_id; INSERT INTO public.rental_notices(user_id,subject,body,dedupe) SELECT CASE WHEN adm THEN t.user_id ELSE a.user_id END,'Mensagem no suporte','Há uma atualização no chamado #'||t.id||'.','support:'||new_id||':'||a.user_id FROM public.rental_admins a ON CONFLICT(dedupe) DO NOTHING; END IF;
-- Registra ou remove inscrições push previamente validadas pela Edge Function.
ELSIF p_action='push' THEN IF COALESCE((p_data->>'remove')::boolean,false) THEN DELETE FROM public.rental_push WHERE user_id=p_actor AND endpoint=p_data->>'endpoint'; ELSE INSERT INTO public.rental_push(user_id,endpoint,data) VALUES(p_actor,p_data->>'endpoint',p_data) ON CONFLICT(endpoint) DO UPDATE SET user_id=excluded.user_id,data=excluded.data; END IF;
-- Prepara pagamento único ou agrupado sem aceitar valores escolhidos pelo navegador.
ELSIF p_action='checkout' THEN SELECT array_agg(v::bigint) INTO ids FROM jsonb_array_elements_text(p_data->'invoice_ids') v; IF COALESCE(array_length(ids,1),0) NOT BETWEEN 1 AND 60 OR (SELECT COUNT(DISTINCT x) FROM unnest(ids) x)<>array_length(ids,1) THEN RAISE EXCEPTION 'Selecione até 60 faturas sem repetição.'; END IF; SELECT a.* INTO l FROM public.rental_leases a JOIN public.rental_invoices i ON i.lease_id=a.id WHERE i.id=ids[1]; IF NOT FOUND OR (NOT adm AND l.user_id<>p_actor) THEN RAISE EXCEPTION 'Fatura indisponível.'; END IF; IF (SELECT COUNT(*) FROM public.rental_invoices WHERE rental_invoices.id=ANY(ids) AND lease_id=l.id AND status='open')<>array_length(ids,1) OR EXISTS(SELECT 1 FROM public.rental_invoice_locks WHERE invoice_id=ANY(ids)) THEN RAISE EXCEPTION 'Uma fatura está paga, reservada ou pertence a outro contrato.'; END IF; SELECT SUM(public.rental_total(i)) INTO value FROM public.rental_invoices i WHERE i.id=ANY(ids); ref=(p_data->>'checkout_id')::uuid; IF value=0 THEN UPDATE public.rental_invoices SET status='paid',paid_at=now(),paid_amount=0,mp_payment='ISENTO' WHERE rental_invoices.id=ANY(ids); RETURN jsonb_build_object('zero',true); END IF; INSERT INTO public.rental_checkouts(id,user_id,lease_id,amount) VALUES(ref,l.user_id,l.id,value); INSERT INTO public.rental_checkout_items SELECT ref,i.id,public.rental_total(i) FROM public.rental_invoices i WHERE i.id=ANY(ids); INSERT INTO public.rental_invoice_locks SELECT x,ref,now()+interval '30 minutes' FROM unnest(ids) x; RETURN jsonb_build_object('id',ref,'amount',value);
-- Não aceita ações desconhecidas ou tentativas de alterar pagamentos pelo navegador.
ELSE RAISE EXCEPTION 'Operação não reconhecida.';
-- Finaliza a seleção da operação.
END IF;
-- Registra a operação sem copiar documentos ou credenciais para a auditoria.
INSERT INTO public.rental_audit(actor,action,detail) VALUES(p_actor,p_action,jsonb_build_object('lease_id',p_data->>'lease_id','id',new_id));
-- Retorna apenas confirmação e identificador necessários à interface.
RETURN jsonb_build_object('ok',true,'id',new_id);
-- Finaliza o processamento transacional.
END $$;
-- Confirma pagamentos somente pela Edge Function após consultar a API oficial do Mercado Pago.
CREATE OR REPLACE FUNCTION public.rental_confirm_payment(p_ref uuid,p_mp text,p_amount bigint,p_paid timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE c record; i record; BEGIN PERFORM pg_advisory_xact_lock(18402672); IF EXISTS(SELECT 1 FROM public.rental_payments WHERE mp_id=p_mp) THEN RETURN jsonb_build_object('duplicate',true); END IF; SELECT * INTO c FROM public.rental_checkouts WHERE id=p_ref; IF NOT FOUND OR c.amount<>p_amount THEN RAISE EXCEPTION 'Valor ou referência divergente.'; END IF; IF c.status='paid' OR EXISTS(SELECT 1 FROM public.rental_checkout_items x JOIN public.rental_invoices f ON f.id=x.invoice_id WHERE x.checkout_id=p_ref AND f.status<>'open') THEN INSERT INTO public.rental_payments VALUES(p_mp,p_ref,p_amount,p_paid,'needs_review'); RETURN jsonb_build_object('review',true); END IF; INSERT INTO public.rental_payments VALUES(p_mp,p_ref,p_amount,p_paid,'approved'); FOR i IN SELECT * FROM public.rental_checkout_items WHERE checkout_id=p_ref LOOP UPDATE public.rental_invoices SET status='paid',paid_at=p_paid,paid_amount=i.amount,mp_payment=p_mp WHERE id=i.invoice_id; INSERT INTO public.rental_notices(user_id,subject,body,dedupe) VALUES(c.user_id,'Pagamento confirmado','Seu recibo PDF está disponível para a fatura #'||i.invoice_id||'.','paid:'||i.invoice_id) ON CONFLICT(dedupe) DO NOTHING; END LOOP; UPDATE public.rental_checkouts SET status='paid',payment_id=p_mp WHERE id=p_ref; DELETE FROM public.rental_invoice_locks WHERE checkout_id=p_ref; RETURN jsonb_build_object('ok',true); END $$;
-- Gera avisos periódicos sem duplicar a mesma cobrança no mesmo dia.
CREATE OR REPLACE FUNCTION public.rental_reminders() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE l record; i record; BEGIN PERFORM pg_advisory_xact_lock(18402672); FOR l IN SELECT id FROM public.rental_leases WHERE status='active' LOOP PERFORM public.rental_generate(l.id); PERFORM public.rental_allocate(l.id); END LOOP; FOR i IN SELECT f.*,a.user_id FROM public.rental_invoices f JOIN public.rental_leases a ON a.id=f.lease_id WHERE f.status='open' AND f.due<=CURRENT_DATE+3 LOOP INSERT INTO public.rental_notices(user_id,subject,body,dedupe) VALUES(i.user_id,CASE WHEN i.due<CURRENT_DATE THEN 'Aluguel em atraso' ELSE 'Lembrete de aluguel' END,'Consulte a fatura #'||i.id||', vencimento '||i.due||', na sua conta.','reminder:'||i.id||':'||CURRENT_DATE) ON CONFLICT(dedupe) DO NOTHING; END LOOP; END $$;
-- Habilita RLS sem políticas públicas: leituras e operações passam pela Edge Function autenticada.
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename LIKE 'rental_%' LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t.tablename); EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated',t.tablename); EXECUTE format('GRANT ALL ON public.%I TO service_role',t.tablename); END LOOP; END $$;
-- Somente a função de servidor pode executar as rotinas com privilégios.
DO $$ DECLARE f record; BEGIN FOR f IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'rental_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated',f.signature); EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f.signature); EXECUTE format('ALTER FUNCTION %s SET timezone TO %L',f.signature,'America/Sao_Paulo'); END LOOP; END $$;
-- Permite que a Edge Function utilize os identificadores automáticos das novas tabelas.
DO $$ DECLARE q record; BEGIN FOR q IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='S' AND c.relname LIKE 'rental_%' LOOP EXECUTE format('GRANT USAGE,SELECT ON SEQUENCE public.%I TO service_role',q.relname); END LOOP; END $$;
-- Cria um bucket privado para comprovantes com limite de 8 MB e formatos permitidos.
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('rental-proofs','rental-proofs',false,8388608,ARRAY['application/pdf','image/jpeg','image/png']) ON CONFLICT(id) DO UPDATE SET public=false,file_size_limit=8388608,allowed_mime_types=EXCLUDED.allowed_mime_types;
-- O usuário só pode enviar arquivos na pasta identificada por seu próprio UUID.
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE policyname='rental_upload_own' AND schemaname='storage') THEN CREATE POLICY rental_upload_own ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='rental-proofs' AND (storage.foldername(name))[1]=auth.uid()::text); END IF; END $$;
-- Não expõe listagem ou leitura pública; a Edge Function emite links temporários após autorizar o titular.
COMMIT;
